HTML = '''<!doctype html><html lang="pt-BR"><meta charset="utf-8"><title>Placares — PES6 Studio</title>
<style>*{box-sizing:border-box}body{background:#10151f;color:#e5edf7;font:16px system-ui;margin:24px;max-width:1200px}a{color:#8fcbff}button,select,input{padding:10px;margin:5px;background:#24344d;color:white;border:1px solid #587192;border-radius:6px}button{cursor:pointer}button:disabled{opacity:.5;cursor:wait}.grid{display:flex;gap:24px;flex-wrap:wrap}.preview{background-color:#333;background-image:conic-gradient(#222 25%,transparent 0 50%,#222 0 75%,transparent 0);background-size:20px 20px;width:384px;height:384px;object-fit:contain;image-rendering:pixelated;border:1px solid #587192}small{color:#acbdd3}#status{min-height:24px}section{padding:20px 0;border-top:1px solid #33445b}</style>
<nav><a href="/">Galeria</a> · <a href="/clubs">Clubes</a> · <a href="/leagues">Ligas</a></nav>
<h1>Placares e HUD</h1><p>Exporte uma textura original, edite o PNG mantendo as posições e dimensões, importe e confira a conversão.</p>
<p><strong>Disponível: um placar global.</strong> A seleção automática por competição ainda está em investigação. Alterar nomes de ligas não cria essa seleção. O layout e as posições dos objetos permanecem os do jogo.</p>
<select id="resource" aria-label="Textura"></select><p id="detail"></p><div class="grid"><div><h3>Original</h3><img id="original" class="preview" alt="Atlas original"><p><a id="download">Baixar PNG original</a></p></div><div><h3>Prévia convertida</h3><img id="modified" class="preview" alt="Atlas convertido"></div></div>
<input id="file" type="file" accept="image/png"><button id="import">Importar PNG</button><button id="undo">Restaurar textura</button><p><small>Os números são atualizados nas duas cópias encontradas. O atlas contém vários elementos: esta prévia não simula uma partida.</small></p>
<p id="status" role="status"></p><section><button id="save">Salvar projeto</button><button id="load">Carregar projeto</button><select id="mode"><option value="img">Gerar IMG</option><option value="iso">Gerar ISO</option></select><button id="build">Gerar patch</button><button id="open" hidden>Abrir pasta gerada</button><p id="output" role="status"></p></section>
<script>const $=id=>document.getElementById(id);let state,dir;async function api(url,body){const r=await fetch(url,body===undefined?{}:{method:'POST',body});const d=await r.json();if(!r.ok||d.error)throw Error(d.error||r.statusText);return d}async function refresh(){state=await api('/scoreboards/data');let key=$('resource').value;$('resource').replaceChildren(...state.resources.map(r=>new Option(r.label+(r.modified?' *':''),r.key)));if(state.resources.some(r=>r.key===key))$('resource').value=key;show()}function show(){const k=$('resource').value,r=state.resources.find(r=>r.key===k),v=Date.now();$('original').src='/scoreboards/png?key='+k+'&original=1';$('modified').src='/scoreboards/png?key='+k+'&v='+v;$('download').href='/scoreboards/png?key='+k+'&original=1&download=1';$('detail').textContent=r.width+' × '+r.height+' px — rv_e.img: '+r.locations.map(p=>'entrada '+p.entry+', parte '+p.part+' ('+p.name+')').join(' / ')}$('resource').onchange=show;async function run(action){try{await action()}catch(e){$('status').textContent=e.message}}$('import').onclick=()=>run(async()=>{let f=$('file').files[0];if(!f)throw Error('Selecione um PNG');$('status').textContent='Convertendo e verificando espaço no arquivo…';await api('/scoreboards/stage?key='+$('resource').value,f);await refresh();$('status').textContent='Textura preparada. Confira a prévia e salve o projeto.'});$('undo').onclick=()=>run(async()=>{await api('/scoreboards/undo?key='+$('resource').value,'');await refresh();$('status').textContent='Textura restaurada.'});$('save').onclick=()=>run(async()=>{$('status').textContent=(await api('/save','')).message});$('load').onclick=()=>run(async()=>{if(!confirm('Substituir as alterações atuais pelo projeto salvo?'))return;let r=await api('/load','');await refresh();$('status').textContent=r.message});$('build').onclick=()=>run(async()=>{try{$('build').disabled=true;$('open').hidden=true;$('output').textContent='Gerando e verificando os arquivos…';let r=await api('/build?mode='+$('mode').value,'');dir=r.output_directory;$('output').textContent='Arquivos verificados: '+r.files.join(' | ');$('open').hidden=false}catch(e){$('output').textContent=e.message}finally{$('build').disabled=false}});$('open').onclick=()=>run(async()=>{await api('/openOutput',JSON.stringify({directory:dir}))});run(refresh);</script></html>'''
